const fs = require('fs');
const path = require('path');

const mcqs = [];

function addCS(id, topic, testTag, difficulty, question, options, answerIndex, explanation) {
    mcqs.push({
        id: `cs_${id.toString().padStart(3, '0')}`,
        subjectId: "computer",
        topic: topic,
        testTag: testTag,
        difficulty: difficulty,
        isPastPaper: true,
        question: question,
        options: options.map(String),
        answer: answerIndex,
        explanation: explanation || `Standard past paper Computer Science question for ${topic} (${testTag}).`
    });
}

